func AbsoluteIsSmall(
	number int64,
) bool {
	absolute := number
	if number < 0 {
		absolute = -number
	}
	if !(absolute >= 0) {
		panic(
			"Assertion failed: absolute >= 0",
		)
	}
	return absolute < 1000
}

